select.where:

    AND m.member_no like concat('%', #{memberNo}, '%')


    AND m.member_name like concat('%', #{memberName}, '%')


    AND m.phone like concat('%', #{phone}, '%')


    AND m.card_type = #{cardType}


    AND m.status = #{status}


    AND m.create_time >= #{params.beginTime}


    AND m.create_time < DATE_ADD(#{params.endTime}, INTERVAL 1 DAY)

AND m.del_flag = '0'
${params.dataScope}

mapper.select:
select count(1) from mem_member

    AND member_no = #{memberNo} and del_flag = '0'

        AND member_id != #{memberId}

select next_value from mem_member_no_sequence
where dept_id = #{deptId} and prefix = #{prefix}
for update

mapper.update:
update mem_member
dept_id = #{deptId}, member_no = #{memberNo}, member_name = #{memberName}, phone = #{phone}, age = #{age}, address = #{address}, id_card = #{idCard}, card_type = #{cardType}, card_id = #{cardId}, join_date = #{joinDate}, expire_date = #{expireDate}, total_points = #{totalPoints}, available_points = #{availablePoints}, growth_value = #{growthValue}, last_active_time = #{lastActiveTime}, status = #{status}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where member_id = #{memberId}

update mem_member set status = '1', update_time = sysdate(), update_by = 'system'
where status = '0' and del_flag = '0'
  and expire_date is not null and expire_date < #{today}
